<script lang="ts">
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import RocketBankSection from './RocketBankSection.svelte';
  import RocketLoanSection from './RocketLoanSection.svelte';
  import RocketStakingSection from './RocketStakingSection.svelte';
  import RocketCasinoCard from './RocketCasinoCard.svelte';

  type RocketSection = 'bank' | 'loan' | 'staking' | 'casino';

  const { trackGameLanguage } = useGameLanguageTick();

  let section = $state<RocketSection>('bank');
  let labels = $derived.by(() => {
    trackGameLanguage();
    return {
      aria: uiText('teamRocket.subTabsAriaLabel', 'Team Rocket sections', {}, game),
      bank: uiText('teamRocket.subTabBank', 'Bank', {}, game),
      loan: uiText('teamRocket.subTabLoan', 'Loan', {}, game),
      staking: uiText('teamRocket.subTabStaking', 'Staking', {}, game),
      casino: uiText('teamRocket.subTabCasino', 'Casino', {}, game),
    };
  });

  function selectSection(next: RocketSection): void {
    section = next;
  }
</script>

<div class="sub-tabs-container tr-sub-tabs" role="tablist" aria-label={labels.aria}>
  <button
    type="button"
    class={['sub-tab-btn', section === 'bank' && 'active']}
    role="tab"
    aria-selected={section === 'bank'}
    onclick={() => selectSection('bank')}
  >{labels.bank}</button>
  <button
    type="button"
    class={['sub-tab-btn', section === 'loan' && 'active']}
    role="tab"
    aria-selected={section === 'loan'}
    onclick={() => selectSection('loan')}
  >{labels.loan}</button>
  <button
    type="button"
    class={['sub-tab-btn', section === 'staking' && 'active']}
    role="tab"
    aria-selected={section === 'staking'}
    onclick={() => selectSection('staking')}
  >{labels.staking}</button>
  <button
    type="button"
    class={['sub-tab-btn', section === 'casino' && 'active']}
    role="tab"
    aria-selected={section === 'casino'}
    onclick={() => selectSection('casino')}
  >{labels.casino}</button>
</div>

<div
  class={[
    'tr-rocket-sections',
    section === 'bank' && 'is-bank',
    section === 'loan' && 'is-loan',
    section === 'staking' && 'is-staking',
    section === 'casino' && 'is-casino',
  ]}
>
  <div class="team-rocket-grid team-rocket-grid--top">
    <div class="tr-pane tr-pane-bank">
      <RocketBankSection />
    </div>
    <div class="tr-pane tr-pane-loan">
      <RocketLoanSection />
    </div>
  </div>

  <div class="tr-pane tr-pane-staking">
    <RocketStakingSection />
  </div>
  <div class="tr-pane tr-pane-casino">
    <RocketCasinoCard />
  </div>
</div>
