<script lang="ts">
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import { touchTooltipHandlers } from '../../ui/scheduleTooltipHelpers.ts';

  interface Props {
    title: string;
    introTooltip: string;
  }

  let { title, introTooltip }: Props = $props();

  const { trackGameLanguage } = useGameLanguageTick();

  let kpi = $derived(rocket.snapshot.kpi);
  let rt = $derived(rocket.realtime);
  let rj = $derived(rt.rj || kpi.rj);
  let subtitle = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.bannerSubtitle', 'Clandestine operations and RJ tokens', {}, game);
  });
  let rjTooltipTitle = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.rjTooltipTitle', 'Rocket Tokens (RJ)', {}, game);
  });
  let rjTooltipBody = $derived.by(() => {
    trackGameLanguage();
    return uiText(
      'teamRocket.rjTooltipBody',
      'Team Rocket exclusive currency. Used for staking and Rocket Casino spins.',
      {},
      game,
    );
  });

  const trustTooltipHandlers = touchTooltipHandlers(() => ({
    title: kpi.trustTooltipTitle,
    body: kpi.trustTooltipBody,
  }));
  const introTip = touchTooltipHandlers(() => ({
    title,
    body: introTooltip.replace(/\n/g, '<br>'),
  }));
  const rjTip = touchTooltipHandlers(() => ({
    title: rjTooltipTitle,
    body: rjTooltipBody,
  }));

  function showPinned(e: MouseEvent, show: (event: MouseEvent) => void): void {
    e.preventDefault();
    e.stopPropagation();
    game?.pinTooltipOpenedByTap?.();
    show(e);
  }
</script>

<div class="tr-banner" id="rocketTopBanner">
  <div class="tr-banner-brand">
    <div class="tr-banner-logo-badge" aria-hidden="true">R</div>
    <div class="tr-banner-identity">
      <div class="tr-banner-title-row">
        <h3 class="tr-banner-title" id="teamRocketTitleLabel">{title}</h3>
        {#if introTooltip}
          <button
            type="button"
            class="tr-section-tooltip-hint"
            aria-label={title}
            onmouseenter={introTip.onmouseenter}
            onmouseleave={introTip.onmouseleave}
            onfocus={introTip.onfocus}
            onblur={introTip.onblur}
            onclick={(e) => showPinned(e, introTip.onmouseenter)}
            onkeydown={introTip.onkeydown}
          >?</button>
        {/if}
      </div>
      <div class="tr-banner-subtitle tr-text-muted">{subtitle}</div>
    </div>
  </div>

  <div class="tr-banner-kpis">
    <!-- RJ KPI -->
    <div
      class="tr-banner-kpi-tile"
      role="button"
      tabindex="0"
      onmouseenter={rjTip.onmouseenter}
      onmouseleave={rjTip.onmouseleave}
      onfocus={rjTip.onfocus}
      onblur={rjTip.onblur}
      onclick={(e) => showPinned(e, rjTip.onmouseenter)}
      onkeydown={rjTip.onkeydown}
    >
      <div class="tr-banner-kpi-val-row">
        <span class="tr-banner-kpi-val tr-text-value" id="rocketKpiRjValue">{rj}</span>
      </div>
      <div class="tr-banner-kpi-lbl tr-text-muted tr-text-muted--caps">{kpi.labelRj}</div>
    </div>

    <!-- Trust KPI -->
    <div
      class="tr-banner-kpi-tile tr-trust-tile--tooltip-host"
      data-tooltip-variant="rocket-trust"
      tabindex="0"
      role="button"
      aria-label={kpi.trustTooltipTitle}
      {...trustTooltipHandlers}
    >
      <div class="tr-banner-kpi-val-row">
        <span class="tr-banner-kpi-val tr-text-value">{kpi.trustLevelText}</span>
      </div>
      <div class={['tr-trust-xp-bar', kpi.trustIsMax && 'is-max']} aria-hidden="true">
        <div class="tr-trust-xp-fill" style:width="{kpi.trustXpRatio.toFixed(2)}%"></div>
      </div>
      <div class="tr-banner-kpi-progress-lbl tr-text-muted tr-text-muted--caps">
        <span>{kpi.labelTrust}</span>
        <span class="tr-trust-xp-text">{kpi.trustNextXpText}</span>
      </div>
    </div>
  </div>
</div>
