<script lang="ts">
  import type { Snippet } from 'svelte';
  import { touchTooltipHandlers } from '../../ui/scheduleTooltipHelpers.ts';

  interface Props {
    title: string;
    tooltip?: string;
    summaryText?: string;
    statusPill?: string;
    statusPillVariant?: 'ok' | 'warn' | 'danger';
    id?: string;
    children?: Snippet;
  }

  let {
    title,
    tooltip = '',
    summaryText = '',
    statusPill = '',
    statusPillVariant = 'ok',
    id,
    children,
  }: Props = $props();

  const hintTip = touchTooltipHandlers(() => ({
    title,
    body: tooltip.replace(/\n/g, '<br>'),
  }));

  function showPinnedHint(e: MouseEvent): void {
    e.preventDefault();
    e.stopPropagation();
    const host = (globalThis as { game?: { pinTooltipOpenedByTap?: () => void } }).game;
    host?.pinTooltipOpenedByTap?.();
    hintTip.onmouseenter(e);
  }
</script>

<section class="tr-collapsible-section" {id}>
  <div class="tr-section-summary-row">
    <div class="tr-section-heading-with-hint">
      <span class="tr-section-heading-text">{title}</span>
      {#if tooltip}
        <button
          type="button"
          class="tr-section-tooltip-hint"
          aria-label={title}
          onmouseenter={hintTip.onmouseenter}
          onmouseleave={hintTip.onmouseleave}
          onfocus={hintTip.onfocus}
          onblur={hintTip.onblur}
          onclick={showPinnedHint}
          onkeydown={hintTip.onkeydown}
        >?</button>
      {/if}
    </div>
    <div class="tr-section-summary">
      {#if statusPill}
        <span class="tr-section-status-pill tr-section-status-pill--{statusPillVariant}">{statusPill}</span>
      {/if}
      {#if summaryText}
        <span class="tr-section-summary-preview">{summaryText}</span>
      {/if}
    </div>
  </div>
  <div class="tr-section-body">
    {@render children?.()}
  </div>
</section>
