<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- item icons from snapshot */
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import type { RocketStakingSessionSnapshot } from '../../bus/snapshots.js';
  import RocketCollapsibleSection from './RocketCollapsibleSection.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  let staking = $derived(rocket.snapshot.staking);
  let rt = $derived(rocket.realtime);
  let timerText = $derived(rt.stakingTimerText || staking.timerText);
  let summaryText = $derived(rt.stakingSummaryText || staking.summaryText);
  let session = $derived(
    staking.session
      ? ((rt.session ?? staking.session) as RocketStakingSessionSnapshot)
      : null,
  );
  let stakingTooltip = $derived(
    session ? timerText : `${timerText}\n${staking.noSessionText}`,
  );
  let sessionPill = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.stakeSessionActive', 'Session active', {}, game);
  });
  let tierLabel = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.stakeTierBadge', 'Tier {tier}', { tier: session?.tier ?? 1 }, game);
  });
  let dismissLabel = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.dismissStealAlert', 'Dismiss alert', {}, game);
  });
  let stakeLockedTitle = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.stakeUnavailableTitle', 'Item unavailable or session active', {}, game);
  });
</script>

<div class="tr-section">
  <RocketCollapsibleSection
    title={staking.sectionTitle}
    tooltip={stakingTooltip}
    {summaryText}
    statusPill={session ? sessionPill : ''}
    statusPillVariant={session?.isHighRisk ? 'danger' : 'ok'}
    id="rocketStakingCollapsible"
  >
    <!-- Compact 1-line steal alert with closing cross -->
    {#if staking.stealFeedback}
      <div class="tr-steal-compact-alert" role="alert">
        <span class="tr-steal-compact-icon" aria-hidden="true">⚠</span>
        <span class="tr-steal-compact-text">{staking.stealFeedback.compactText}</span>
        <button
          type="button"
          class="tr-steal-compact-close"
          data-action="handleRocketDismissStealFeedback"
          aria-label={dismissLabel}
          title={dismissLabel}
        >✕</button>
      </div>
    {/if}

    <div id="rocketStakingMount">
      <!-- Active session card with central risk bar -->
      {#if session}
        <div class={['shop-item tr-session-active-card', session.isHighRisk && 'rocket-risk-shake']}>
          <div class="tr-session-header">
            <div class="tr-session-title-wrap">
              <span class="tr-text-title">{session.sessionTitle}</span>
              <span class="tr-session-tier-badge">{tierLabel}</span>
            </div>
            <div class="tr-text-body" id="rocketPushSessionItemText">
              {session.objectLine}
            </div>
          </div>

          <!-- Central Push-Your-Luck Risk Gauge (Green -> Amber -> Red) -->
          <div class="tr-risk-gauge-box">
            <div class="tr-risk-gauge-header">
              <span
                id="rocketPushRiskLive"
                class={[
                  'tr-risk-label',
                  session.riskBarPct < 10 && 'is-low',
                  session.riskBarPct >= 10 && session.riskBarPct <= 25 && 'is-mid',
                  session.riskBarPct > 25 && 'is-high',
                ]}
              >
                {session.riskText}
              </span>
              {#if session.nextTierHint}
                <span class="tr-next-tier-hint tr-text-muted" id="rocketPushNextTierHint">{session.nextTierHint}</span>
              {/if}
            </div>
            <div class="tr-risk-bar-track">
              <div
                class={[
                  'tr-risk-bar-fill',
                  session.riskBarPct < 10 && 'is-low',
                  session.riskBarPct >= 10 && session.riskBarPct <= 25 && 'is-mid',
                  session.riskBarPct > 25 && 'is-high',
                ]}
                style:width="{Math.max(4, session.riskBarPct)}%"
              ></div>
            </div>
          </div>

          <!-- Live stats & timer -->
          <div class="rocket-push-live-wrap">
            <div
              id="rocketPushTimerCircle"
              class="rocket-push-timer-circle"
              style="--progress:{session.progressPct.toFixed(2)};"
            >
              <div id="rocketPushTimerText" class="tr-text-value tr-text-value--sm">{session.timerText}</div>
            </div>
            <div class="tr-session-live-info">
              <div class="tr-session-accumulated tr-currency-green" id="rocketPushRjLive">
                +{session.accumulatedText}
              </div>
              <div class="tr-text-body tr-session-gps" id="rocketPushGpsLive">
                {session.gpsText}
              </div>
            </div>
            <button
              type="button"
              class="tr-preset-btn tr-action-btn tr-action-btn--primary tr-session-recover-btn"
              data-action="handleRocketRecoverStake"
            >
              {session.recoverButton}
            </button>
          </div>
        </div>
      {/if}

      <!-- Compact 1-line item list (teintée icon, name, rarity, owned, +RJ/s, red Miser button) -->
      <div class="tr-stake-list">
        {#each staking.stakeableItems as item (item.key)}
          <div class={['shop-item tr-stake-row', !item.canStake && 'not-affordable']}>
            <div class="tr-stake-row-left">
              <div class="tr-stake-icon" aria-hidden="true">{@html item.iconHtml}</div>
              <div class="tr-stake-row-info">
                <div class="tr-stake-row-title-line">
                  <span class="tr-stake-name">{item.displayName}</span>
                  <span class="tr-stake-category-chip">{item.categoryLabel}</span>
                </div>
                <div class="tr-stake-row-sub">
                  <span class="tr-stake-owned tr-text-muted">{item.ownedLine}</span>
                </div>
              </div>
            </div>

            <div class="tr-stake-row-right">
              <span class="tr-stake-rate-pill">+{item.baseGpsFormatted}&nbsp;RJ/s</span>
              <button
                type="button"
                class="tr-preset-btn tr-action-btn tr-action-btn--primary tr-stake-action-btn"
                data-action="handleRocketStartContract"
                data-arg={item.key}
                disabled={!item.canStake}
                title={!item.canStake ? stakeLockedTitle : ''}
              >
                {item.stakeButton}
              </button>
            </div>
          </div>
        {:else}
          {#if staking.emptyMessage}
            <div class="shop-item tr-stake-empty">
              <p class="tr-text-muted">{staking.emptyMessage}</p>
            </div>
          {/if}
        {/each}
      </div>
    </div>
  </RocketCollapsibleSection>
</div>
