<script lang="ts">
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import RocketCollapsibleSection from './RocketCollapsibleSection.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  let bank = $derived(rocket.snapshot.bank);
  let rt = $derived(rocket.realtime);
  let gaugeText = $derived(rt.bankGaugeText || bank.bankGaugeText);
  let autoDepositTip = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.bankAutoDepositTip', 'Automatic deposit settings', {}, game);
  });
  let amountPlaceholder = $derived.by(() => {
    trackGameLanguage();
    return uiText('teamRocket.bankAmountPlaceholder', 'Amount (e.g. 250M, 1.5B)', {}, game);
  });
  let summaryText = $derived(rt.bankSummaryText || bank.summaryText);
  let bankFillPct = $derived(rt.bankFillPct ?? bank.bankFillPct);
  let bankAtCap = $derived(rt.bankAtCap ?? bank.bankAtCap);
  let interestPerMin = $derived(rt.interestPerMin || bank.interestPerMin);
  let interestPerHour = $derived(rt.interestPerHour || bank.interestPerHour);
  let projection24h = $derived(rt.projection24h || bank.projection24h);

  let activeMode: 'deposit' | 'withdraw' = $state('deposit');
</script>

<div class="tr-section">
  <RocketCollapsibleSection
    title={bank.bankTitle}
    tooltip={bank.rateText}
    {summaryText}
    statusPill={bank.withdrawAvailableText}
    statusPillVariant="ok"
    id="rocketBankCollapsible"
  >
    <div class="shop-item tr-bank-card" id="rocketBankCard">
      <div class="tr-bank-gauge-card">
        <div class="tr-bank-gauge-header">
          <span class="tr-bank-gauge-line tr-currency-gold" id="rocketBankBalanceText">{gaugeText}</span>
          <button
            type="button"
            class="tr-bank-gear-btn"
            data-action="handleRocketBankOptionsToggle"
            title={autoDepositTip}
          >
            <span aria-hidden="true">&#9881;</span>
            <span>{bank.bankOptionsTitle}</span>
          </button>
        </div>
        <div class="tr-bank-bar-track">
          <div
            class={['tr-bank-bar-fill', bankAtCap && 'is-full']}
            style:width="{bankFillPct}%"
          ></div>
        </div>
        {#if bankAtCap}
          <div class="tr-text-status tr-text-status--warn tr-bank-cap-alert" role="status">
            <span>⚠</span>
            <span>{bank.bankAtCapHint}</span>
          </div>
        {/if}
      </div>

      <!-- Segmented Deposit | Withdraw control -->
      <div class="tr-bank-controls">
        <div class="tr-mode-toggle" role="tablist" aria-label="Mode de transaction bancaire">
          <button
            type="button"
            role="tab"
            aria-selected={activeMode === 'deposit'}
            class={['tr-mode-tab', activeMode === 'deposit' && 'is-active']}
            onclick={() => activeMode = 'deposit'}
          >
            {bank.depositButton}
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={activeMode === 'withdraw'}
            class={['tr-mode-tab', activeMode === 'withdraw' && 'is-active']}
            onclick={() => activeMode = 'withdraw'}
          >
            {bank.withdrawButton}
          </button>
        </div>

        {#if activeMode === 'deposit'}
          <div class="tr-input-row tr-input-row--action tr-input-row--floating-anchor" id="rocketBankDepositRow">
            <input
              id="rocketBankDepositInput"
              class="tr-amount-input"
              type="text"
              inputmode="text"
              placeholder={amountPlaceholder}
              disabled={bankAtCap}
            />
            <div class="tr-preset-segmented" role="group" aria-label="Pourcentages de dépôt">
              <button type="button" class="tr-preset-segment" data-action="setRocketBankDepositPreset" data-arg="0.25" disabled={bankAtCap}>25%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankDepositPreset" data-arg="0.5" disabled={bankAtCap}>50%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankDepositPreset" data-arg="0.75" disabled={bankAtCap}>75%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankDepositPreset" data-arg="1" disabled={bankAtCap}>Max</button>
            </div>
            <button
              type="button"
              class="tr-preset-btn tr-action-btn tr-action-btn--primary"
              data-action="handleRocketDeposit"
              disabled={bankAtCap}
              title={bankAtCap ? bank.bankAtCapHint : ''}
            >
              {bank.depositButton}
            </button>
          </div>
        {:else}
          <div class="tr-input-row tr-input-row--action tr-input-row--floating-anchor" id="rocketBankWithdrawRow">
            <input
              id="rocketBankWithdrawInput"
              class="tr-amount-input"
              type="text"
              inputmode="text"
              placeholder={amountPlaceholder}
            />
            <div class="tr-preset-segmented" role="group" aria-label="Pourcentages de retrait">
              <button type="button" class="tr-preset-segment" data-action="setRocketBankWithdrawPreset" data-arg="0.25">25%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankWithdrawPreset" data-arg="0.5">50%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankWithdrawPreset" data-arg="0.75">75%</button>
              <button type="button" class="tr-preset-segment" data-action="setRocketBankWithdrawPreset" data-arg="1">Max</button>
            </div>
            <button
              type="button"
              class="tr-preset-btn tr-action-btn tr-action-btn--primary"
              data-action="handleRocketWithdraw"
            >
              {bank.withdrawButton}
            </button>
          </div>
        {/if}
      </div>

      <!-- Interest tracker: 3 clean boxes with white values and muted gray labels -->
      <div class="tr-interest-tracker tr-interest-tracker-compact" id="rocketInterestTracker">
        <div class="tr-interest-tracker-grid tr-interest-tracker-grid-3">
          <div class="tr-interest-tracker-cell">
            <div class="tr-text-value" id="rocketInterestInstantPerMin">{interestPerMin}</div>
            <div class="tr-text-muted tr-text-muted--caps">{bank.interestLabelMin}</div>
          </div>
          <div class="tr-interest-tracker-cell">
            <div class="tr-text-value" id="rocketInterestInstantPerHour">{interestPerHour}</div>
            <div class="tr-text-muted tr-text-muted--caps">{bank.interestLabelHour}</div>
          </div>
          <div class="tr-interest-tracker-cell">
            <div class="tr-text-value" id="rocketInterestProj24h">{projection24h}</div>
            <div class="tr-text-muted tr-text-muted--caps">{bank.interestLabelProj}</div>
          </div>
        </div>
      </div>

      <!-- Expandable bank options -->
      <div class={['tr-bank-options', bank.optionsOpen && 'open']}>
        <label class="tr-checkbox-label tr-text-body">
          <input
            type="checkbox"
            checked={bank.autoInjectCombatHalf}
            onchange={(e) => game.handleRocketAutoInjectCombatHalfToggle((e.currentTarget as HTMLInputElement).checked)}
          />
          {bank.injectCombatHalf}
        </label>
        <label class="tr-checkbox-label tr-text-body">
          <input
            type="checkbox"
            checked={bank.autoInjectInterests}
            onchange={(e) => game.handleRocketAutoInjectInterestsToggle((e.currentTarget as HTMLInputElement).checked)}
          />
          {bank.injectInterests}
        </label>
      </div>
    </div>
  </RocketCollapsibleSection>
</div>
